1H8N7-2:
\begin{ex}%[1H8N7-2]
	\immini{
		Cho hình chóp $S.ABC$ có đáy là tam giác vuông cân tại $B$, $SA \perp (ABC)$, $AB=BC=a$, $SA=a\sqrt{3}$. Tính thể tích $V$ của khối chóp nói trên.
		\choice
		{$V=\dfrac{a^3}{6}$}
		{\True $V=\dfrac{a^3\sqrt{3}}{6}$}
		{$V=a^3\sqrt{3}$}
		{$V=\dfrac{a^3\sqrt{3}}{2}$}
	}{
		\begin{tikzpicture}[line join=round, line cap=round, font=\footnotesize]
			\coordinate (A) at (0,0);
			\coordinate (B) at (1,-1);
			\coordinate (C) at (2.5,0);
			\coordinate (S) at (0,2.5);
			\draw (S)--(A)--(B)--(C)--(S)--(B);
			\draw[dashed] (A)--(C);
			\draw (A)++(0,0.2)--++(0.2,0)--++(0,-0.2);
			\draw (B)++(-0.15,0.12)--++(0.2,0.1)--++(0.1,-0.18);
			\foreach \P/\g in {S/90,A/180,B/-90,C/0}
			\fill (\P) circle (1pt) ($(\P)+(\g:3mm)$) node{$\P$};
		\end{tikzpicture}
	}
	\loigiai{
		Diện tích đáy $S_{ABC} = \dfrac{1}{2} AB \cdot BC = \dfrac{a^2}{2}$[cite: 35].\\
		Thể tích khối chóp $V = \dfrac{1}{3} S_{ABC} \cdot SA = \dfrac{1}{3} \cdot \dfrac{a^2}{2} \cdot a\sqrt{3} = \dfrac{a^3\sqrt{3}}{6}$.
	}
\end{ex}

2D1N5-1:
\begin{ex}%[2D1N5-1]
	\immini[thm]{
	Đường cong trong hình bên là đồ thị của hàm số nào dưới đây?
	\choice
	{$y = -x^3 + 3x - 4$}
	{$y = -x^3 + 3x^2 + 4$}
	{\True $y = -x^3 + 3x^2 - 4$}
	{$y = x^3 + 3x^2 - 4$}
	}{
	\begin{tikzpicture}[>=stealth, line join=round, line cap=round, every node/.style={font=\footnotesize}, declare function={f(\x)=-\x*\x*\x + 3*\x*\x - 4; xmin=-1.5; xmax=4.5; ymin=-5.5; ymax=2.5;},scale=0.6, yscale=0.8]

		\draw[-stealth, line width=0.7pt] (xmin, 0) -- (xmax, 0) node[below] {$x$};
		\draw[-stealth, line width=0.7pt] (0, ymin) -- (0, ymax) node[shift={(-6pt,-5pt)}] {$y$};

		\fill (0,0) circle (1pt) node[shift={(-135:10pt)}] {$O$};

		\begin{scope}
			\clip (xmin, ymin) rectangle (xmax, ymax);
			\draw[line width=0.6pt, smooth, samples=300, domain=xmin:xmax] plot (\x, {f(\x)});
		\end{scope}

		\foreach \x/\pos in {-1/-135,  2/90} {
			\fill (\x, 0) circle (1pt) node[shift={(\pos:8pt)}] {$\x$};
		}

		\foreach \y/\pos in {1/180, -4/-180} {
			\fill (0, \y) circle (1pt) node[shift={(\pos:8pt)}] {$\y$};
		}

	\end{tikzpicture}
	}

	\loigiai{
		Dựa vào đồ thị, ta thấy hệ số $a < 0$ nên loại phương án D.\\
		Đồ thị hàm số cắt trục tung tại điểm có tung độ bằng $-4$, do đó $y(0) = -4$ nên loại phương án B.\\
		Đồ thị hàm số đi qua điểm $(2; 0)$. Ta thay $x = 2$ vào các hàm số còn lại
		\begin{itemize}
			\item Với $y = -x^3 + 3x - 4$, ta có $y(2) = -2^3 + 3 \cdot 2 - 4 = -6 \neq 0$ (loại).
			\item Với $y = -x^3 + 3x^2 - 4$, ta có $y(2) = -2^3 + 3 \cdot 2^2 - 4 = -8 + 12 - 4 = 0$ (thỏa mãn).
		\end{itemize}
		Vậy hàm số cần tìm là $y = -x^3 + 3x^2 - 4$.
	}
\end{ex}

2H2N1-1:
\begin{ex}%[2H2N1-1]
Cho tứ diện $ABCD$. Gọi $M, N$ lần lượt là trung điểm của $AD$ và $BC$. Tổng $\overrightarrow{AB}+\overrightarrow{DC}$ bằng 
\choice
{$\overrightarrow{0}$}
{$2\overrightarrow{NM}$}
{$2\overrightarrow{AD}$}
{\True $2\overrightarrow{MN}$}
\loigiai{
\immini{
Ta có
\begin{itemize}
\item $\overrightarrow{AB}=\overrightarrow{AM}+\overrightarrow{MN}+\overrightarrow{NB}$.
\item $\overrightarrow{DC}=\overrightarrow{DM}+\overrightarrow{MN}+\overrightarrow{NC}$.
\end{itemize}
Khi đó,
\begin{align*}
\overrightarrow{AB}+\overrightarrow{DC}&=\overrightarrow{AM}+\overrightarrow{MN}+\overrightarrow{NB}+\overrightarrow{DM}+\overrightarrow{MN}+\overrightarrow{NC}\\
&=(\overrightarrow{AM}+\overrightarrow{DM})+(\overrightarrow{NB}+\overrightarrow{NC})+2\overrightarrow{MN}\\
&=\overrightarrow{0}+\overrightarrow{0}+2\overrightarrow{MN}\\
&=2\overrightarrow{MN}.
\end{align*}
Vì $m$, $N$ lần lượt là trung điểm $AD$ và $BC$ nên $\overrightarrow{AM}+\overrightarrow{DM}=\overrightarrow{0}$ và $\overrightarrow{NB}+\overrightarrow{NC}=\overrightarrow{0}$.
}{\begin{tikzpicture}[>=stealth,line join=round,line cap=round]
\draw[black,scale=2.5] (0,0)coordinate(B)--(-35:0.8)coordinate(C)--(1,0)coordinate(D);
\draw[dashed,black,scale=2.5] ($(C)!.5!(D)$)coordinate(M1) ($(B)!2/3!(M1)$)coordinate(H) (B)--(D) ($(H)+(90:1)$)coordinate(A);
\draw[black,scale=2.5] (B)--(A)--(D) (A)--(C);
\path ($(A)!0.5!(D)$) coordinate (M);
\path ($(B)!0.5!(C)$) coordinate (N);
\foreach \diem/\vitrin in {A/above,B/left,C/below left,D/right,M/right,N/left}	\fill (\diem)circle(1.5pt)node[\vitrin]{$\diem$};
\end{tikzpicture}}}
\end{ex}

