	\itemch Ta có tọa độ các đỉnh của mái che là $H\left(0;0;5\right)$, $G\left(0;5;4\right)$ và $E\left(6;0;3\right)$. \\
	$\vec{HE} = \left(6;0;-2\right)$, $\vec{HG} = \left(0;5;-1\right)$. \\
