	\draw (M)--(H) (H)--(A) (K)--(A) (M)--(N) (K)--(N);
	\node[left] at (H) {$H$};
	\node[right] at (K) {$K$};
	\node[below left] at (A) {$A$};
	\node[above] at (M) {$M$};
	\node[right] at (N) {$N$};
	\node[above] at (I) {$I$};
