	{Sau $24$ giây kể từ khi tăng tốc, tốc độ của ô tô không vượt quá tốc độ tối đa cho phép là $100 \text{ km/h}$}
	{Quãng đường $S(t)$ (đơn vị: mét) mà ô tô đi được trong thời gian $t$ giây $(0\le t\le24)$ kể từ khi tăng tốc được tính theo công thức: $S(t)=\displaystyle\int\limits_{0}^{24}v(t)\mathrm{d}t$}
	\loigiai{
		\begin{itemchoice}
			\itemch Đổi $36 \text{ km/h} = 10 \text{ m/s}$.\\
			Lúc $t=0$, ô tô bắt đầu tăng tốc sau khi đã chạy ổn định $3$ giây với vận tốc $10 \text{ m/s}$.\\
			Vận tốc tại thời điểm bắt đầu tăng tốc là $v(0) = a \cdot 0 + b = b \Rightarrow b = 10$.
			\itemch Trong $3$ giây đầu (trước khi tăng tốc), ô tô đi được quãng đường là $10 \cdot 3 = 30 \text{ m}$.\\
			Vì khoảng cách ban đầu đến điểm nhập làn là $210 \text{ m}$, nên quãng đường ô tô đi được từ khi bắt đầu tăng tốc đến khi nhập làn là $210 - 30 = 180 \text{ m}$.
			\itemch Ô tô nhập làn sau $12$ giây kể từ khi tăng tốc, nên quãng đường đi được là\\ $\displaystyle\int\limits_{0}^{12} (at+10)\mathrm{d}t = 180$ $\Leftrightarrow \left(a\dfrac{t^2}{2} + 10t\right)\bigg|_0^{12} = 180 \Leftrightarrow 72a + 120 = 180 \Leftrightarrow a = \dfrac{5}{6}$.\\
			Phương trình vận tốc là $v(t) = \dfrac{5}{6}t + 10$.\\
			Sau $24$ giây, tốc độ của ô tô là $v(24) = \dfrac{5}{6} \cdot 24 + 10 = 30 \text{ m/s} = 108 \text{ km/h}$.\\
			Tốc độ này lớn hơn $100 \text{ km/h}$.
			\itemch Quãng đường $S(t)$ đi được trong thời gian $t$ giây kể từ khi tăng tốc phải được tính bằng biểu thức tích phân $\displaystyle\int\limits_{0}^{t}v(x)\mathrm{d}x$, trong khi công thức đề bài cho là $\displaystyle\int\limits_0^{24}v(t)\mathrm{d}t$ (đây là một hằng số thể hiện tổng quãng đường đi được trong $24$ giây).
		\end{itemchoice}
	}
\end{ex}

2D1H3-1:
\begin{ex}%[2D1H3-1]
	Cho hàm số $f(x)=\dfrac{4}{x}+x+1$ với $x \neq 0$. 
	\choiceTF
	{\True Đạo hàm của hàm số đã cho là $f'(x)=\dfrac{x^2-4}{x^2}$ với $x \neq 0$}
	{ $f'(-4)=2$}
	{Tổng các nghiệm của phương trình $f'(x)=0$ bằng 4}
	{\True Hàm số $f(x)$ có giá trị lớn nhất và giá trị nhỏ nhất trên đoạn $[1;3]$ lần lượt bằng $M,m$. Khi đó $M-m=1$}
	\loigiai{
		\begin{itemchoice}
			\itemch Ta có $f'(x) = -\dfrac{4}{x^2} + 1 = \dfrac{x^2-4}{x^2}$. 
			\itemch $f'(-4) = \dfrac{(-4)^2-4}{(-4)^2} = \dfrac{12}{16} = \dfrac{3}{4}$. 
			\itemch $f'(x)=0 \Leftrightarrow x=\pm 2$. Tổng nghiệm: $2+(-2)=0$. 
			\itemch $f(1)=6, f(2)=5, f(3)=\dfrac{16}{3} \Rightarrow M=6, m=5 \Rightarrow M-m=1$. 
		\end{itemchoice}
	}
\end{ex}

0D0V2-7:
\begin{ex}%[0D0V2-7]
	Trong hộp có $45$ quả cầu có cùng kích thước và khối lượng được đánh số từ $1$ đến $45$. Lấy ngẫu nhiên $3$ quả cầu từ hộp đó. Xét tính đúng sai của các mệnh đề sau:
	\choiceTF
	{\True Số cách lấy được cả $3$ quả cầu đánh số chẵn bằng $1540$}
	{Xác suất để tích $3$ số ghi trên $3$ quả cầu là một số chia hết cho $8$ bằng $\dfrac{523}{1290}$}
	{Xác suất để tổng $3$ số ghi trên $3$ quả cầu là số lẻ bằng $\dfrac{1}{2}$}
	{\True Xác suất để tổng $3$ số ghi trên $3$ quả cầu là số chia hết cho $4$ bằng $\dfrac{323}{1290}$}
	\loigiai{
		\begin{itemchoice}
			\itemch Trong $45$ quả cầu có $22$ quả cầu mang số chẵn, $23$ quả cầu mang số lẻ. Do đó số cách lấy được cả $3$ quả cầu đánh số chẵn bằng $\mathrm{C}_{22}^3=1\,540$ (cách).
			\itemch Ta xét các trường hợp tích $3$ số ghi trên $3$ quả cầu là số không chia hết cho $8$.
			\begin{itemize}
				\item Ba số là ba số lẻ. Số cách lấy là $\mathrm{C}_{23}^3$ (cách).
				\item Trong ba số có $2$ số lẻ, và số chẵn còn lại không chia hết cho $8$. Có $5$ số chia hết cho $8$ ($8, 16, 24, 32, 40$) , do đó có $17$ số chẵn không chia hết cho $8$. Do đó có $\mathrm{C}_{23}^2 \cdot \mathrm{C}_{17}^1$ (cách).
				\item Trong ba số có $1$ số lẻ, và tích $2$ số chẵn còn lại không chia hết cho $8$. Khi đó, $2$ số chẵn còn lại phải có dạng $4k+2, k \in \mathbb{N}$ (có $11$ số như vậy). Do đó có $\mathrm{C}_{23}^1 \cdot \mathrm{C}_{11}^2$ (cách).
			\end{itemize}
			Vậy có $\mathrm{C}_{23}^3+\mathrm{C}_{23}^2 \cdot \mathrm{C}_{17}^1+\mathrm{C}_{23}^1 \cdot \mathrm{C}_{11}^2=7337$ cách để chọn ra $3$ số có tích không chia hết cho $8$. \\
			Số cách chọn ra $3$ số là $\mathrm{C}_{45}^3$ (cách). \\
			Vậy xác suất để tích $3$ số ghi trên $3$ quả cầu là một số chia hết cho $8$ bằng: $1 - \dfrac{7337}{\mathrm{C}_{45}^3}=\dfrac{523}{1290}$.
			\itemch Ta xét các trường hợp để tổng $3$ số được chọn là một số lẻ.
			\begin{itemize}
				\item Cả ba số đều là số lẻ. Số cách chọn là $\mathrm{C}_{23}^3$ (cách chọn)
				\item Trong $3$ số có $1$ số lẻ và $2$ số chẵn. Số cách chọn là $\mathrm{C}_{23}^1 \cdot \mathrm{C}_{22}^2$ (cách chọn).
			\end{itemize}
			Tổng số cách chọn là $\mathrm{C}_{23}^3+\mathrm{C}_{23}^1 \cdot \mathrm{C}_{22}^2=7084$ (cách chọn). \\
			Xác suất để tổng $3$ số ghi trên $3$ quả cầu là số lẻ bằng $\dfrac{7084}{\mathrm{C}_{45}^3}=\dfrac{322}{645}$ .
			\itemch Trong $45$ số, có $11$ số chia $4$ hết cho $4$, $12$ số chia $4$ dư $1$, $11$ số chia $4$ dư $2$ và $11$ số chia $4$ dư $3$. Ta xét các trường hợp để tổng $3$ số ghi trên $3$ quả cầu là số chia hết cho $4$:
			\begin{itemize}
				\item $3$ số đều chia hết cho $4$, số cách chọn là $\mathrm{C}_{11}^3$ (cách).
				\item Có $1$ số chia hết cho $4$ và $2$ số chia $4$ dư $2$. Số cách chọn là $\mathrm{C}_{11}^1 \cdot \mathrm{C}_{11}^2$ (cách).
				\item Có $1$ số chia $4$ dư $2$, và $2$ số chia $4$ dư $1$. Số cách chọn là $\mathrm{C}_{11}^1 \cdot \mathrm{C}_{12}^2$ (cách).
				\item Có $1$ số chia $4$ dư $2$, và $2$ số chia $4$ dư $3$. Số cách chọn là $\mathrm{C}_{11}^1 \cdot \mathrm{C}_{11}^2$ (cách).
				\item Có $1$ số chia hết cho $4$, $1$ số chia $4$ dư $1$ và $1$ số chia $4$ dư $3$. Số cách chọn là $\mathrm{C}_{11}^1 \cdot \mathrm{C}_{12}^1 \cdot \mathrm{C}_{11}^1$ (cách chọn).
			\end{itemize}
			Tổng số cách chọn là $\mathrm{C}_{11}^4+\mathrm{C}_{11}^1 \cdot \mathrm{C}_{11}^2+\mathrm{C}_{11}^1 \cdot \mathrm{C}_{12}^2+\mathrm{C}_{11}^1 \cdot \mathrm{C}_{11}^2+\mathrm{C}_{11}^1 \cdot \mathrm{C}_{12}^1 \cdot \mathrm{C}_{11}^1=3\,553$ (cách). \\
			Xác suất để tổng $3$ số ghi trên $3$ quả cầu là số chia hết cho $4$ là $\mathrm{P}=\dfrac{3\,553}{\mathrm{C}_{45}^3}=\dfrac{323}{1\,290}$.
		\end{itemchoice}
	}
\end{ex}

