1D7V2-5:
\begin{ex}%[1D7V2-5]
	\immini{
		Hình vẽ dưới đây mô tả một cây cầu vượt có mặt cắt đứng là một phần parabol nối hai điểm $A$, $B$ và nhận đường trung trực của đoạn $AB$ làm trục đối xứng, $AB=400$ m. Khoảng cách từ đỉnh cây cầu đến $AB$ bằng $8$ m. Xét tiếp tuyến $d$ tại điểm $M$ trên mặt cầu, người ta quy ước $\tan(\Delta,d)$ là độ dốc tại $M$ của mặt cầu, với $\Delta$ là đường thẳng đi qua hai điểm $A$, $B$. Độ dốc lớn nhất của mặt cầu là bao nhiêu?
	}{
		\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=0.8]
			\coordinate (A) at (-4,0);
			\coordinate (B) at (4,0);
			\coordinate (O) at (0,0);
			\coordinate (S) at (0,2);
			\draw (A)--(B);
			\draw[thick, domain=-4:4, samples=100] plot (\x, {-0.125*\x*\x + 2});
			\draw (0,0)--(0,2) node[midway, right] {$8$ m};
			\node[below] at (A) {$A$};
			\node[below] at (B) {$B$};
			\node[below] at (O) {$O$};
			\node[below] at (-2,0) {$200$ m};
			\node[below] at (2,0) {$200$ m};
			\fill (A) circle (1.5pt);
			\fill (B) circle (1.5pt);
			\fill (O) circle (1.5pt);
			\coordinate (M) at (-2.4,1.28);
			\fill (M) circle (1.5pt) node[above left] {$M$};
			\draw (-4.5, 0.02) -- (0.5, 3.02) node[right] {$d$};
			\draw (-2.4,1.28) -- (-0.4,1.28);
			\draw (-1.4,1.28) arc (0:30.96:1);
			\node[rotate=30.96] at (-1.1, 2.4) {Độ dốc tại $M$};
		\end{tikzpicture}
	}
	\shortans{0.08}
	\loigiai{
		Chọn hệ trục tọa độ $Oxy$ sao cho gốc tọa độ $O$ là trung điểm của đoạn thẳng $AB$, tia $Ox$ chứa điểm $B$, tia $Oy$ đi qua đỉnh của cây cầu.\\
		Theo giả thiết $AB = 400$, ta có tọa độ các điểm: $A(-200; 0)$, $B(200; 0)$. Đỉnh cây cầu cao $8$ m nên $S(0; 8)$.\\
		Do parabol nhận trục $Oy$ làm trục đối xứng nên phương trình có dạng $y = ax^2 + c$.\\
		Parabol có đỉnh là $S(0; 8)$ nằm trên trục $Oy$ nên $c=8$, phương trình trở thành $y = ax^2 + 8$.\\
		Parabol đi qua điểm $B(200; 0)$ nên ta có: $a \cdot 200^2 + 8 = 0 \Leftrightarrow a = -\dfrac{8}{40000} = -\dfrac{1}{5000}$.\\
		Vậy phương trình mặt cắt đứng của cây cầu là $y = -\dfrac{1}{5000}x^2 + 8$ với tập xác định $x \in [-200; 200]$.\\
		Vì $\Delta$ là đường thẳng đi qua $A, B$ nên $\Delta$ trùng với trục hoành $Ox$.\\
		Độ dốc của mặt cầu tại điểm $M(x; y)$ là $k = \tan(\Delta, d) = |y'(x)|$.\\
		Ta có đạo hàm: $y'(x) = 2 \cdot \left(-\dfrac{1}{5000}\right)x = -\dfrac{1}{2500}x$.\\
		Suy ra hàm số thể hiện độ dốc là $k = |y'(x)| = \left|-\dfrac{1}{2500}x\right| = \dfrac{|x|}{2500}$.\\
		Vì $M$ thuộc đoạn cầu từ $A$ đến $B$ nên $x \in [-200; 200] \Leftrightarrow |x| \le 200$.\\
		Do đó, ta có đánh giá: $k = \dfrac{|x|}{2500} \le \dfrac{200}{2500} = 0{,}08$.\\
		Dấu "=" xảy ra khi và chỉ khi $|x| = 200 \Leftrightarrow x = \pm 200$, tức là tại hai đầu $A$ hoặc $B$ của cây cầu.\\
		Vậy độ dốc lớn nhất của mặt cầu là $0{,}08$.
	}
\end{ex}

2H2V2-6:
\begin{ex}%[2H2V2-6]
	Trong không gian với hệ tọa độ $Oxyz$ (đơn vị trên mỗi trục là $10\text{ km}$), hai khinh khí cầu A và B bay với vectơ vận tốc lần lượt là $\vec{v_a}=(1;2;0)$ và $\vec{v_b}=(-2;3;0)$ (đơn vị là $\text{km/giờ}$). Tại thời điểm $t=0$ vị trí của khinh khí cầu A là $M(5;4;2)$ và vị trí của khinh khí cầu B là $N(6;5;3)$. Hai khinh khí cầu sẽ bay trong $10$ giờ tiếp theo và dừng lại.
	\choiceTF
	{\True Sau $3$ giờ vị trí của khinh khí cầu A là $M'(8;10;2)$}
	{Khinh khí cầu B không bay qua vị trí $N'(0;14;3)$}
	{Khoảng cách giữa hai khinh khí cầu sau $3$ giờ là $9\text{ km}$}
	{\True Trong khoảng thời gian từ $t=0$ đến $t=10$ giờ, khoảng cách ngắn nhất giữa hai khinh khí cầu là $16{,}1\text{ km}$ (làm tròn đến hàng phần chục)}
	\loigiai{
		\begin{itemchoice}
			\itemch Giả sử sau $t$ giờ, vị trí máy bay A là $M'$, khi đó ta có $\vec{MM'} = t\vec{v_a} = (t;2t;0)$.\\
			Khi đó $M'(t+5; 2t+4; 2)$.\\
			Với $t=3 \Rightarrow M'(8;10;2)$.
			\itemch Giả sử sau $t$ giờ, vị trí máy bay B là $N'$, khi đó ta có $\vec{NN'} = t\vec{v_b} = (-2t;3t;0)$.\\
			Khi đó $N'(-2t+6; 3t+5; 3)$.\\
			Nếu khinh khí cầu B bay qua vị trí $N'(0;14;3)$ khi đó ta có $\heva{ & -2t+6=0 \\ & 3t+5=14 } \Leftrightarrow t=3$ (thỏa mãn).\\
			Vậy khinh khí cầu B có bay qua vị trí $N'(0;14;3)$.
			\itemch Sau $3$ giờ vị trí khinh khí cầu $B$ là $N'(0;14;3)$.\\
			Khoảng cách giữa hai khinh khí cầu trong không gian $Oxyz$ là $$M'N' = \sqrt{(0-8)^2+(14-10)^2+(3-2)^2} = \sqrt{81} = 9.$$
			Vì mỗi đơn vị trên trục là $10\text{ km}$ nên khoảng cách thực tế là $9 \cdot 10 = 90\text{ km}$.
			\itemch Gọi $t$ là thời điểm hai khinh khí cầu bay ($0 \le t \le 10$).\\
			Khi đó $M'(t+5; 2t+4; 2)$ và $N'(-2t+6; 3t+5; 3)$.\\
			Ta có 
			\allowdisplaybreaks
			\begin{eqnarray*}
				&&\vec{M'N'} = (-3t+1; t+1; 1)\\
				&\Rightarrow& M'N' = \sqrt{(-3t+1)^2+(t+1)^2+1} = \sqrt{10t^2-4t+3} = \sqrt{10\left(t-\dfrac{1}{5}\right)^2+\dfrac{13}{5}} \ge \sqrt{\dfrac{13}{5}}
			\end{eqnarray*}
			Suy ra $M'N'$ đạt giá trị nhỏ nhất là $\sqrt{\dfrac{13}{5}} \approx 1{,}61$ (đơn vị) ứng với $16{,}1\text{ km}$ khi $t=\dfrac{1}{5}$.
		\end{itemchoice}
	}
\end{ex}

