			\itemch Ta có $\overrightarrow{CA} = (-5;-50;-100)$. \\
			Chọn vectơ chỉ phương của đường thẳng $AC$ là $\vec{u} = -\dfrac{1}{5}\overrightarrow{CA} = (1;10;20)$. \\
			Đường thẳng $AC$ đi qua $C(20;60;50)$ và có VTCP $\vec{u} = (1;10;20)$ nên có phương trình chính tắc là
			\[\dfrac{x-20}{1} = \dfrac{y-60}{10} = \dfrac{z-50}{20}.\]
			\itemch Phương trình tham số của quỹ đạo tia laser $AC$ là $\heva{&x = 20+t \\ &y = 60+10t \\ &z = 50+20t.}$ \\
			Điểm phao tiêu $B$ là giao điểm của $AC$ với mặt phẳng $(Oxy) \colon z=0$. \\
			Khi đó $50+20t = 0 \Leftrightarrow t = -2{,}5$. \\
			Tọa độ điểm $B$ là $x_B = 20 + (-2{,}5) = 17{,}5$; $y_B = 60 + 10 \cdot (-2{,}5) = 35$; $z_B = 0$. \\
			Vậy $a+b+c = 17{,}5 + 35 + 0 = 52{,}5$.
			\itemch Quãng đường $s$ tia laser đi trong nước sau $10\,$ns kể từ khi chạm mặt nước là
			\[s = \displaystyle\int\limits_0^{10} (0{,}22+0{,}01t) \mathrm{\,d}t = \left. \left( 0{,}22t + 0{,}005t^2 \right) \right|_0^{10} = 2{,}2 + 0{,}5 = 2{,}7\,\text{m}.\]
			\itemch Vì hình chiếu của $d$ lên mặt nước $(z=0)$ đi qua $B(17{,}5;35;0)$ và có vectơ chỉ phương $\vec{u} = (2;1;0)$, đồng thời thanh ray $d$ cách mặt nước $5\,$m nên $d$ đi qua điểm $(17{,}5;35;5)$ và có cùng VTCP $\vec{u}$. \\
			Phương trình tham số của $d \colon \heva{&x = 17{,}5+2t \\ &y = 35+t \\ &z = 5.}$ \\
			Do $M \in d$ nên $M(17{,}5+2t; 35+t; 5)$. Ta có $\overrightarrow{AM} = (2{,}5+2t; 25+t; 55)$. \\
			Khoảng cách $AM$ ngắn nhất khi và chỉ khi $AM \perp d \Leftrightarrow \overrightarrow{AM} \cdot \vec{u} = 0$:
			\begin{eqnarray*}
				&& 2(2{,}5+2t) + 1(25+t) + 0 \cdot 55 = 0 \\
				&\Leftrightarrow& 5t + 30 = 0 \Leftrightarrow t = -6.
			\end{eqnarray*}
			Suy ra tọa độ robot tối ưu là $M(5{,}5; 29; 5)$. \\
			Khi đó $a'+b'-c' = 5{,}5 + 29 - 5 = 29{,}5$.
		\end{itemchoice}
	}
\end{ex}

