				\node[right] at (B) {$B$};
				\node[right] at (C) {$C$};
				\node[left] at (D) {$D$};

				\node[left] at (Ap) {$A'$};
				\node[right] at (Bp) {$B'$};
				\node[right] at (Cp) {$C'$};
				\node[left] at (Dp) {$D'$};

				\node[left] at (A1) {$A_1$};
				\node[right] at (B1) {$B_1$};
				\node[right] at (C1) {$C_1$};
				\node[left] at (D1) {$D_1$};

				\node[below] at (H) {$H$};
				\node[above right] at (K) {$K$};

