			\draw[-stealth] (6.8, -1.2) -- (4.5, -1.2) -- (3.2, -0.6);
			\node[above right, font=\small, inner sep=1pt] at (4.5, -1.2) {Phần cánh hoa};

			% Ghi chú "Phần lõi"
			\draw[-stealth] (6.8, -2.4) -- (4.5, -2.4) -- (1.5, -1.2);
			\node[above right, font=\small, inner sep=1pt] at (4.5, -2.4) {Phần lõi};

		\end{tikzpicture}
	}
	\par\shortans{329}
	\loigiai{
		\textbf{Bước 1: Viết phương trình đường tròn và elip} \\
		Chọn hệ trục tọa độ $Oxy$ có gốc $O$ trùng với giao điểm của hai trục lớn của hai elip. Khi đó:
		\begin{itemize}
			\item Phương trình elip $(E_1)$ có trục lớn nằm trên trục $Ox$ ($a=4, b=\dfrac{4}{\sqrt{3}}$) là 
			\[\dfrac{x^2}{16} + \dfrac{3y^2}{16} = 1 \Rightarrow y^2 = \dfrac{16-x^2}{3} \Rightarrow y = \sqrt{\dfrac{16-x^2}{3}} \text{ (với } y \ge 0).\]
			\item Do tính đối xứng, giao điểm của hai elip $(E_1)$ và $(E_2)$ nằm trên đường phân giác $y=x$. Thay $y=x$ vào phương trình $(E_1)$ ta được:
			\[\dfrac{x^2}{16} + \dfrac{3x^2}{16} = 1 \Leftrightarrow 4x^2 = 16 \Leftrightarrow x = \pm 2.\]
			Suy ra hoành độ các giao điểm của 2 elip là $x_{1,2} = \pm 2$.
			\item Bán kính đường tròn $(O)$ là $R^2 = x^2 + y^2 = 2x^2 = 2 \cdot 4 = 8$. \\
			Phương trình nửa đường tròn phía trên là $y = \sqrt{8-x^2}$ (với $y \ge 0$).
		\end{itemize}
		\textbf{Bước 2: Tính diện tích các phần (cm$^2$)}
		\begin{itemize}
			\item Diện tích phần lõi hình tròn $(S_1)$: $S_1 = \pi R^2 = 8\pi$ (cm$^2$).
			\item Diện tích phần cánh hoa $(S_2)$: \\
			Do tính đối xứng nên diện tích $4$ cánh hoa bằng $8$ lần diện tích một nửa cánh hoa (giới hạn bởi elip, đường tròn và các trục tọa độ).
			\[S_2 = 8 \times \left( \displaystyle\int\limits_2^4 \sqrt{\dfrac{16-x^2}{3}} \mathrm{\,d}x - \displaystyle\int\limits_2^{2\sqrt{2}} \sqrt{8-x^2} \mathrm{\,d}x \right) \approx 13{,}5616\,\text{cm}^2.\]
		\end{itemize}
		\textbf{Bước 3: Tổng chi phí nguyên vật liệu} \\
		Đơn vị tính: nghìn đồng.
		\[T = S_1 \cdot 5 + S_2 \cdot 15 = 8\pi \cdot 5 + 13{,}5616 \cdot 15 \approx 329{,}088.\]
		Làm tròn đến hàng đơn vị theo yêu cầu đề bài, ta được $329$ nghìn đồng.
	}
\end{ex}

1D2V3-8:
\begin{ex}%[1D2V3-8]
