				\draw[thick] (B) -- (B');
				\draw[thick] (A) -- (A');
				\draw[thick] (A') -- (B');
				\draw[thick] (B') -- (C');
				\draw[thick] (A) -- (B');
				\draw[thick] (A) -- (H);

