		\begin{center}
		  \begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth, declare function={a=5;b=3;goc=30;h=4;}]
		  	% 1. Định nghĩa các đỉnh và trung điểm (sử dụng thư viện calc để lấy trung điểm)
		  	\path (0,0) coordinate (A)
			  	(0:a) coordinate (B)
			  	(180+goc:b) coordinate (D)++(0:a) coordinate (C)
			  	($(A)!0.5!(C)$) coordinate (O)++(90:h) coordinate (S)
			  	($(S)!0.5!(A)$) coordinate (F)
			  	($(S)!0.5!(B)$) coordinate (I);
		  	\draw (S)--(D)--(C)--(B)--(S)--(C);
		  	\draw[dashed] (S)--(A)--(D) (A)--(B) (A)--(C) (B)--(D) (S)--(O);
		  	\draw[dashed, brown] (F)--(C) (F)--(D);
		  	\draw[dashed, red] (O)--(I)--(C) (A)--(I);
		  	\foreach \diem/\vt in {S/90, A/180, B/0, C/-45, D/-135, O/-90, F/135, I/45}{
		  		\fill (\diem) circle (1pt) ($(\diem)+(\vt:3mm)$) node {$\diem$};
		  	}
		  \end{tikzpicture}
		\end{center}
		\begin{itemchoice}
			\itemch Tam giác $SAC$ đều $\left(SA=SC=AC=a\sqrt{2}\right)$ có trung tuyến $FC=\dfrac{\sqrt{3}}{2} \cdot a \sqrt{2}=\dfrac{a \sqrt{6}}{2}$.
			Tam giác $SAD$ có $DF$ là đường trung tuyến $\Rightarrow DF=\sqrt{\dfrac{SD^2+AD^2}{2} - \dfrac{SA^2}{4}}=a$. \\
			Tam giác $FCD$ có $CD=a,\ DF=a,\ FC=\dfrac{a\sqrt{6}}{2}$. Khi đó, ta có
			\begin{eqnarray*}
			  	S_{FCD}&=&\sqrt{p(p-FC)(p-CD)(p-DF)}, \text{ với }  p=\dfrac{FC+CD+DF}{2}=\dfrac{4+\sqrt{6}}{4} \\
			  	&=&\dfrac{\sqrt{15}}{8} \cdot a^2.
			\end{eqnarray*}
			Lại có $V_{S.FCD}=\dfrac{1}{3} d \left( S,(FCD) \right) \cdot S_{FCD} 
			\Rightarrow d\left( S,(FCD) \right)=\dfrac{3V_{S.FCD}}{S_{FCD}}
			=\dfrac{a\sqrt{10}}{5}$.
			\itemch Ta có $\widehat{(SA,(ABCD))}=\widehat{(SA, AO)}=\widehat{SAO}$. \\
			Trong $\triangle SAO$ có $\sin\widehat{SAO}=\dfrac{SO}{SA}=\dfrac{\sqrt{3}}{2} \Rightarrow \widehat{SAO}=60^\circ$. \\
			Như vậy $\widehat{(SA,(ABCD))}=\widehat{(SA, AO)}=60^\circ$.
			\itemch Gọi $O$ là tâm hình vuông $ABCD$, khi đó $SO$ là đường cao của hình chóp $S.ABCD$. \\
			Tam giác vuông $SAO$ có $SA=a \sqrt{2},\ AO=\dfrac{AC}{2}=\dfrac{a \sqrt{2}}{2}$ \\
			$\Rightarrow SO=\sqrt{SA^2 - AO^2}=\sqrt{\left( a \sqrt{2} \right)^2 - \left( \dfrac{a \sqrt{2}}{2} \right)^2}=\dfrac{a \sqrt{6}}{2}.$ \\
			Suy ra $V_{S.ABCD}=\dfrac{1}{3} \cdot SO \cdot S_{ABCD}
			=\dfrac{1}{3} \cdot SO \cdot AB^2=\dfrac{a^3\sqrt{6}}{6}$. \\
			Từ đó $V_{S.FCD}=V_{A.FCD}=\dfrac{1}{2}V_{S.ACD}
			=\dfrac{1}{4}V_{S.ABCD}
			=\dfrac{a^3\sqrt{6}}{24}$.

			\itemch Kẻ $OI \perp SB$ ($I \in SB$). Dễ thấy hình chóp $S.ABCD$ đối xứng qua mặt phẳng $(SAC)$ nên ta có $CI=IA$. Do đó tam giác $AIC$ cân tại $I \Rightarrow OI \perp AC$. Suy ra $\mathrm{d}(AC, SB)=OI$. \\
			Xét tam giác $SOB$ có $\dfrac{1}{OI^2}=\dfrac{1}{SO^2}+\dfrac{1}{OB^2} 
			\Rightarrow OI=\dfrac{a \sqrt{6}}{4}$ hay $\mathrm{d}(AC, SB)=\dfrac{a \sqrt{6}}{4}$.
		\end{itemchoice}
	}
\end{ex}

2D1V5-7:
\begin{ex}%[2D1V5-7]
    Cho hàm số $y = f(x) = \dfrac{2x^2 - 5x + 9}{x - 5}$.
    \choiceTF
    {\True Đồ thị hàm số cắt trục tung tại điểm có tung độ bằng $-\dfrac{9}{5}$}
    {Hàm số nghịch biến trên khoảng $(1;9)$}
    {Có đúng một điểm trên đồ thị hàm số cách đều hai trục tọa độ}
    {Đồ thị hàm số có đường tiệm cận đứng là $y = 5$}
    \loigiai{
	\begin{itemchoice}
	\itemch Đồ thị hàm số cắt trục tung tại điểm có tung độ là $f(0)=-\dfrac{9}{5}$.
	\itemch Vì hàm số không xác định tại điểm $x = 5$.
	\itemch Giả sử điểm $M$ trên đồ thị có tọa độ là $M\left(x;\dfrac{2x^2-5x+9}{x-5}\right)$ với $x\ne5$.\\
Điểm $M$ cách đều hai trục tọa độ nghĩa là
\allowdisplaybreaks
\begin{eqnarray*}
&&|x|=\left|\dfrac{2x^2-5x+9}{x-5}\right|\Leftrightarrow|x^2-5x|=|2x^2-5x+9|\\
&\Leftrightarrow&\hoac{&x^2-5x=2x^2-5x+9\\&x^2-5x=-2x^2+5x-9}\Leftrightarrow\hoac{&x^2+9=0\\&3x^2-10x+9=0}\Leftrightarrow x\in\varnothing.
\end{eqnarray*}
Vậy không có điểm nào thỏa mãn.
	\itemch Đồ thị hàm số có đường tiệm cận đứng là $x = 5$.
	\end{itemchoice}
    }
\end{ex}

1D1V5-3:
\begin{ex}%[1D1V5-3]
Cho phương trình $\cos\left(4x-\dfrac{3\pi}{8}\right)=-1$. Khi đó:
\choiceTF
{\True $x=\dfrac{11\pi}{32}$ là một nghiệm của phương trình đã cho}
{\True Tất cả nghiệm của phương trình đã cho được biểu diễn bởi 4 điểm trên đường tròn lượng giác}
{Tổng nghiệm dương nhỏ nhất và nghiệm âm lớn nhất của phương trình bằng $\dfrac{3\pi}{4}$}
{Tổng các nghiệm trên khoảng $\left(\dfrac{\pi}{4};\dfrac{19\pi}{2}\right)$ của phương trình đã cho là $\dfrac{6061\pi}{32}$}
\loigiai{
\begin{itemchoice}
\itemch Thay $x=\dfrac{11\pi}{32}$ vào phương trình, ta được: $\cos\left(4\cdot \dfrac{11\pi}{32}-\dfrac{3\pi}{8}\right)=\cos\left(\pi\right)=-1$.\\
Vậy $x=\dfrac{11\pi}{32}$ là một nghiệm của phương trình đã cho.
\itemch Ta có: $\cos\left(4x-\dfrac{3\pi}{8}\right)=-1$$\Leftrightarrow 4x-\dfrac{3\pi}{8}=\pi+k 2\pi$$\Leftrightarrow 4x=\dfrac{11\pi}{8}+k 2\pi$$\Leftrightarrow x=\dfrac{11\pi}{32}+\dfrac{k\pi}{2}(k\in\mathbb{Z})$.\\
Áp dụng công thức nghiệm: $x=\alpha+\dfrac{k 2\pi}{n}$ với $n$ là số điểm biểu diễn trên đường tròn lượng giác, ta có: $\Leftrightarrow x=\dfrac{11\pi}{32}+\dfrac{k\pi}{2}=\dfrac{11\pi}{32}+\dfrac{k 2\pi}{4}$. Suy ra $n=4$.\\
Vậy tất cả nghiệm của phương trình đã cho được biểu diễn bởi 4 điểm trên đường tròn lượng giác.
\itemch Xét $x=\dfrac{11\pi}{32}+\dfrac{k\pi}{2}>0$$\Leftrightarrow\dfrac{k\pi}{2}>-\dfrac{11\pi}{32}$$\Leftrightarrow k>-\dfrac{11}{16}$ mà $k\in\mathbb{Z}\Rightarrow$ nghiệm dương nhỏ nhất ứng với $k=0$.\\
Nghiệm dương nhỏ nhất là $\dfrac{11\pi}{32}+\dfrac{0\cdot \pi}{2}=\dfrac{11\pi}{32}$.\\
Xét $x=\dfrac{11\pi}{32}+\dfrac{k\pi}{2}<0$$\Leftrightarrow\dfrac{k\pi}{2}<-\dfrac{11\pi}{32}$$\Leftrightarrow k<-\dfrac{11}{16}$ mà $k\in\mathbb{Z}\Rightarrow$ nghiệm âm lớn nhất ứng với $k=-1$.\\
Nghiệm âm lớn nhất là $\dfrac{11\pi}{32}+\dfrac{(-1)\cdot \pi}{2}=-\dfrac{5\pi}{32}$.\\
Tổng nghiệm dương nhỏ nhất và nghiệm âm lớn nhất của phương trình bằng $\dfrac{11\pi}{32}-\dfrac{5\pi}{32}=\dfrac{3\pi}{16}$.
\itemch Ta có
\allowdisplaybreaks
\begin{eqnarray*}
x\in\left(\dfrac{\pi}{4};\dfrac{19\pi}{2}\right)&\Leftrightarrow&\dfrac{\pi}{4}<x<\dfrac{19\pi}{2}\\
&\Leftrightarrow&\dfrac{\pi}{4}<\dfrac{11\pi}{32}+\dfrac{k\pi}{2}<\dfrac{19\pi}{2}\\
&\Leftrightarrow&\dfrac{1}{4}<\dfrac{11}{32}+\dfrac{k}{2}<\dfrac{19}{2}\\
&\Leftrightarrow&-\dfrac{3}{32}<\dfrac{k}{2}<\dfrac{293}{32}\\
&\Leftrightarrow&-\dfrac{3}{16}<k<\dfrac{293}{16},k\in\mathbb{Z}\\
&\Rightarrow& k\in\{0;1;2;\ldots;17;18\}
\end{eqnarray*}
Thay các giá trị của $k$ vào $x=\dfrac{11\pi}{32}+\dfrac{k\pi}{2}$ ta được tập hợp các nghiệm trên khoảng $\left(\dfrac{\pi}{4};\dfrac{19\pi}{2}\right)$: $x\in\left\{\dfrac{11\pi}{32};\dfrac{11\pi}{32}+\dfrac{\pi}{2};\dfrac{11\pi}{32}+\dfrac{2\pi}{2};\ldots;\dfrac{11\pi}{32}+\dfrac{17\pi}{2};\dfrac{11\pi}{32}+\dfrac{18\pi}{2}\right\}$.\\
Tính tổng các nghiệm có 2 cách:
\begin{itemize}
\item Cách 1: Bấm máy $\sum\limits_{k=0}^{18}\left(\dfrac{11\pi}{32}+\dfrac{k\pi}{2}\right)=\dfrac{2945\pi}{32}$.
\item Cách 2: Tính: $\dfrac{11\pi}{32}+\left(\dfrac{11\pi}{32}+\dfrac{\pi}{2}\right)+\left(\dfrac{11\pi}{32}+\dfrac{2\pi}{2}\right)+\cdots+\left(\dfrac{11\pi}{32}+\dfrac{17\pi}{2}\right)+\left(\dfrac{11\pi}{32}+\dfrac{18\pi}{2}\right)$.\\
Coi mỗi nghiệm là 1 số hạng trong cấp số cộng với $x_1=\dfrac{11\pi}{32}$, công sai $d=\dfrac{\pi}{2}$.\\
Do $k\in\{0;1;2;\ldots;17;18\}$ nên số số hạng $n=19$.\\
Tổng các nghiệm là: $S=\dfrac{\left(x_1+x_{19}\right)\cdot n}{2}=\dfrac{\left(\dfrac{11\pi}{32}+\dfrac{11\pi}{32}+\dfrac{18\pi}{2}\right)\cdot 19}{2}=\dfrac{2945\pi}{32}$.
\end{itemize}
\end{itemchoice}
}
\end{ex}

1D6V4-6:
\begin{ex}%[1D6V4-6]
Trong âm nhạc, một quãng tám (Boctave) là khoảng cách âm thanh từ nốt Đô tới nốt Đồ tiếp theo, theo thứ tự từ thấp đến cao là
\begin{center}
Đô - Đô$\sharp$ - Rê - Rê$\sharp$ - Mi(E4) - Pha - Pha$\sharp$ - Sol - Sol$\sharp$ - La (A4) - La$\sharp$ - Si - Đô
\end{center}
trong đó khoảng cách giữa hai nốt liên tiếp gọi là một nửa cung (semitone). Hai nốt cách nhau $n$ nửa cung thì tỷ lệ tần số nốt cao $f_\text{nc}$ và tằn số nốt thấp $f_\text{nt}$ là $\dfrac{f_\text{nc}}{f_\text{nt}}=2^{\tfrac{x}{12}}$; cho biết tần số chuẩn cùa nốt La (A4) là $440$
Hz. Trên đàn guitar, dây số $1$ là nốt Mi(E4) đang bị chùng do thời tiết, tần số đo được hiện tại đang là $300$
Hz. Để căng lại dây đàn cho chuẩn, ta dùng núm xoay, và cứ vặn núm xoay $90^{\circ}$ thì nốt nhạc được tăng lên một nửa cung. Hỏi phải xoay núm của dây số $1$ một góc bao nhiêu độ để dây số $1$ trở về âm chuẩn \textit{(không làm tròn các buớc trung gian, chi làm tròn kết quả cuối cùng tới hàng đơn vị)}?
\shortans[]{$147$}
\loigiai{
Từ Mi (E4) đến La (A4) có
\begin{center}
Mi $\rightarrow$ Pha (1), Pha $\rightarrow$ Pha$\sharp$ (2), Pha$\sharp$ $\rightarrow$ Sol (3), Sol $\rightarrow$ Sol$\sharp$ (4), Sol$\sharp$ $\rightarrow$ La (5).
\end{center}
Vậy Mi (E4) và La (A4) cách nhau $5$ nửa cung.\\
Ta có $\dfrac{f_\text{La}}{f_\text{Mi}}=2^{\tfrac{5}{12}}$ suy ra tần số chuẩn của Mi (E4) là $f_\text{Mi}=\dfrac{f_\text{La}}{2^{\tfrac{5}{12}}}=\dfrac{440}{2^{\tfrac{5}{12}}}$ Hz.\\
Gọi $n$ là số nửa cung cần tăng để từ $300$ Hz lên âm chuẩn của Mi , ta có
\begin{eqnarray*}
& &\dfrac{f_\text{Mi}}{300}=2^{\tfrac{n}{12}}\\
&\Leftrightarrow& \dfrac{440}{300 \cdot 2^{\tfrac{5}{12}}}=2^{\tfrac{n}{12}} \\
& \Leftrightarrow& \dfrac{n}{12}=\log _2\left(\dfrac{440}{300\cdot 2^{\tfrac{5}{12}}}\right)\\
&\Leftrightarrow& n=12 \cdot \log _2\left(\dfrac{22}{15\cdot 2^{\dfrac{5}{12}}}\right).
\end{eqnarray*}
Góc xoay cần thiết là $\alpha=n\cdot 90^{\circ}=12\cdot \log _2\left(\dfrac{22}{15\cdot 2^{\tfrac{5}{12}}}\right)\cdot 90^{\circ} \approx 147^{\circ}$.
}
\end{ex}

