		\item Công sai $d=2$: $\{9, 11, 13\}, \{10, 12, 14\}, \{11, 13, 15\}, \{12, 14, 16\}$ (có $4$ bộ).
		\item Công sai $d=3$: $\{9, 12, 15\}, \{10, 13, 16\}$ (có $2$ bộ).
	\end{itemize}
