1D2H2-6:
\begin{ex}%[1D2H2-6]
	Cho cấp số cộng $(u_n)$ có $u_1=\dfrac{1}{4}$ và $d=-\dfrac{1}{4}$. Gọi $S_5$ là tổng $5$ số hạng đầu tiên của cấp số cộng đã cho. Mệnh đề nào sau đây đúng?
	\choice
	{$S_5=\dfrac{5}{4}$}
	{\True $S_5=-\dfrac{5}{4}$}
	{$S_5=\dfrac{4}{5}$}
	{$S_5=-\dfrac{4}{5}$}
	\loigiai{
		Tổng $5$ số hạng đầu tiên của cấp số cộng là
		\[S_5 = \dfrac{5(2u_1 + 4d)}{2} = \dfrac{5\left[2 \cdot \dfrac{1}{4} + 4 \cdot \left(-\dfrac{1}{4}\right)\right]}{2} = \dfrac{5\left(\dfrac{1}{2} - 1\right)}{2} = \dfrac{5 \cdot \left(-\dfrac{1}{2}\right)}{2} = -\dfrac{5}{4}.\]
	}
\end{ex}

1D6H4-5:
\begin{ex}%[1D6H4-5]
	Bất phương trình $1+\log_2(x-2) > \log_2(x^2-3x+2)$ có tập nghiệm là
	\choice
	{\True $S=(2;3)$}
	{$S=(3;+\infty)$}
	{$S=(2;+\infty)$}
	{$S=(1;3)$}
	\loigiai{
		Điều kiện $\heva{& x-2>0 \\ & x^2-3x+2>0} \Leftrightarrow \heva{& x>2 \\ & \hoac{&x<1 \\ &x>2}} \Leftrightarrow x>2$.\\
		Bất phương trình $1+\log_2(x-2) > \log_2(x^2-3x+2)$
		\begin{align*}
			&\Leftrightarrow \log_2 2 + \log_2(x-2) > \log_2(x^2-3x+2) \\
			&\Leftrightarrow \log_2 2(x-2) > \log_2(x^2-3x+2) \\
			&\Rightarrow 2(x-2) > x^2-3x+2 \\
			&\Leftrightarrow x^2-5x+6 < 0 \\
			&\Leftrightarrow 2 < x < 3
		\end{align*}
		Kết hợp điều kiện ta được $2 < x < 3$. Vậy tập nghiệm là $S=(2;3)$.
	}
\end{ex}

