2D1C5-4:
\begin{ex}%[2D1C5-4]
	Cho hàm số $\displaystyle y = f(x) = \frac{ax^2 + bx + c}{x + d}$ có đồ thị là đường cong như hình vẽ.
	\begin{center}
		\begin{tikzpicture}[>=stealth, scale=0.8]
			% Giới hạn khung hình để đồ thị không bị tràn khi x tiến gần 2
			\clip (-4,-5) rectangle (6,5);

			% Vẽ trục hoành Ox và trục tung Oy
			\draw[->] (-3.5,0) -- (5.5,0) node[above] {$x$};
			\draw[->] (0,-4.65) -- (0,4.5) node[right] {$y$};
			\node[below left] at (0,0) {$O$};

			% Đường tiệm cận đứng x = 2
			\draw[solid] (2,-4.65) -- (2,4.5);
			\node[below left] at (2,0) {$2$};

			% Đường tiệm cận xiên y = -x
			\draw[solid, domain=-3.7:4.7] plot (\x, {-\x});

			% Vẽ đồ thị hàm số nhánh bên trái (x < 2)
			\draw[thick, smooth, samples=100, domain=-3.5:1.15] 
			plot (\x, {(-\x*\x + 2*\x + 3) / (\x - 2)});

			% Vẽ đồ thị hàm số nhánh bên phải (x > 2)
			\draw[thick, smooth, samples=100, domain=2.43:5.5] 
			plot (\x, {(-\x*\x + 2*\x + 3) / (\x - 2)});

			% Đánh dấu các giao điểm với trục tọa độ
			\fill (3,0) circle (1.5pt) node[below right] {$3$};
			\fill (-1,0) circle (1.5pt) node[below left] {$-1$};
			\fill (0,-1.5) circle (1.5pt) node[left] {$-\frac{3}{2}$};

		\end{tikzpicture}
	\end{center}
	\choiceTF
	{Đạo hàm của hàm số $y = f(x)$ luôn dương $\forall x \in \mathbb{R} \setminus \{2\}$}
	{\True Tổng của hai hệ số $c$ và $d$ bằng $1$}
	{\True Đồ thị hàm số $y = f(x)$ có tiệm cận xiên là đường thẳng $y = -x$}
	{\True Để đường thẳng $y = m$ cắt đồ thị hàm số $y = f(x)$ tại hai điểm phân biệt $A$ và $B$ sao cho $OA \perp OB$ thì $m$ là nghiệm của phương trình $m^2 - 2m - 3 = 0$}
	\loigiai
	{
		\begin{itemchoice}
			\itemch Dựa vào đồ thị hàm số nghịch biến nên đạo hàm của hàm số $y = f(x)$ luôn âm $\forall x \in \mathbb{R} \setminus \{2\}$. Chọn SAI.
			\itemch Đồ thị hàm số đi qua $\left(0; -\frac{3}{2}\right) \Rightarrow \frac{c}{d} = -\frac{3}{2} \Rightarrow c = -\frac{3}{2}d$.\\
			Ta có tiệm cận đứng $x = 2 \Rightarrow d = -2 \Rightarrow c = 3$.\\
			Khi đó $c + d = 1$. Chọn ĐÚNG.
			\itemch Đồ thị hàm số đi qua $(-1; 0)$ và $(3; 0)$ suy ra\\
			$\begin{cases} 0 = \frac{a - b + 3}{-1 - 2} \\ 0 = \frac{9a + 3b + 3}{3 - 2} \end{cases} \Leftrightarrow \begin{cases} a - b = -3 \\ 3a + b = -1 \end{cases} \Leftrightarrow \begin{cases} a = -1 \\ b = 2 \end{cases}$.\\
			$\displaystyle \Rightarrow y = f(x) = \frac{-x^2 + 2x + 3}{x - 2} = -x + \frac{3}{x - 2}$.\\
			Tiệm cận xiên là $y = -x$. Chọn ĐÚNG.
			\itemch Xét phương trình $\displaystyle f(x) = m \Leftrightarrow \frac{-x^2 + 2x + 3}{x - 2} = m$, ĐK $x \neq 2$.\\
			$\displaystyle \frac{-x^2 + 2x + 3}{x - 2} = m \Rightarrow x^2 + (m - 2)x - 3 - 2m = 0$ (*)\\
			Phương trình (*) có $\Delta = (m + 2)^2 + 12 > 0 \, \forall m$, nên nó luôn có hai nghiệm phân biệt.\\
			Để đồ thị hàm số $y = f(x)$ cắt đường thẳng $y = m$ tại hai điểm phân biệt thì $m \neq \frac{7}{2}$.\\
			$A(x_1; m), B(x_2; m) \Rightarrow OA \perp OB \Leftrightarrow x_1 \cdot x_2 + m^2 = 0 \Leftrightarrow -3 - 2m + m^2 = 0 \Leftrightarrow m^2 - 2m - 3 = 0$. Chọn ĐÚNG.
		\end{itemchoice}
	}
\end{ex}

2H5V3-2:
\begin{ex}%[2H5V3-2]
	Một quả bóng hình cầu có bán kính $r$ đang được treo trong một góc của tường nhà. Một điểm $B$ cố định nằm trên mép hai bờ tường và cách mặt đất $56$ cm, sợi dây treo quả bóng có độ dài $AB = 20$ cm và đây cũng là độ dài ngắn nhất nối điểm $B$ với mặt xung quanh của quả bóng. 
	\begin{center}
		\begin{tikzpicture}[scale=0.5,>=stealth]
			% Hai mặt tường
			\fill[gray!15] (0,0) rectangle (5,7);
			\fill[gray!25] (-3,-2) -- (0,0) -- (0,7) -- (-3,5);

			% Trục tọa độ
			\draw[->] (0,0) -- (-3,-2) node[below] {$x$};
			\draw[->] (0,0) -- (5,0) node[below] {$y$};
			\draw[->] (0,0) -- (0,7) node[above] {$z$};

			% Quả bóng tiếp xúc hai tường
			\shade[ball color=gray!40] (0.7,2.5) circle (1.4);

			% Gốc tọa độ
			\node[below] at (0,0) {$O$};

			% Điểm B
			\coordinate (B) at (0,5.8);
			\fill (B) circle (1pt);
			\node[left] at (B) {$B$};

			% Điểm A trên mặt cầu
			\coordinate (A) at (0.6,3.9);
			\fill (A) circle (1pt);
			\node[above right] at (A) {$A$};

			% Dây treo
			\draw[thick] (B)--(A);

			% Kí hiệu 12cm
			\draw[<->] (0.7,-0.5) -- (0.7,1.1);
			\node[right] at (0.6,0.5) {$12\,\mathrm{cm}$};
		\end{tikzpicture}
	\end{center}
Biết rằng quả bóng tiếp xúc với hai bên bờ tường và điểm thấp nhất của quả bóng cách mặt đất $12$ cm. Hỏi quả bóng có đường kính là bao nhiêu cm?
	\par\shortans{$32$}
	\loigiai{
		Gọi $I$ là tâm quả bóng, $r$ là bán kính. Quả bóng tiếp xúc với hai tường và cách sàn $12$ cm nên tâm $I$ có tọa độ $(r, r, r+12)$.\\
		Khoảng cách từ $B(0,0,56)$ đến tâm $I$ là $BI = \sqrt{r^2 + r^2 + (56 - (r+12))^2} = \sqrt{2r^2 + (44-r)^2}$.\\
		Vì $AB = 20$ là khoảng cách ngắn nhất từ $B$ đến mặt cầu nên $BI = AB + r = 20 + r$.\\
		Từ đó ta có $\sqrt{2r^2 + (44-r)^2} = 20+r \Leftrightarrow r^2 - 64r + 768 = 0 \Leftrightarrow (r-16)(r-48) = 0$.\\
		Vì $r < 44$ nên $r = 16$. Vậy đường kính quả bóng hình cầu là $2r = 32$ cm.
	}
\end{ex}

0D0H2-7:
\begin{ex}%[0D0H2-7]
	Một hộp chứa $10$ tấm thẻ cùng loại được đánh số từ $1$ đến $10$. Bạn Bình lấy ra lần lượt $2$ tấm thẻ từ hộp. Thẻ lấy ra lần thứ nhất không được trả lại hộp. Xác suất của biến cố \lq\lq Tổng các số trên $2$ tấm thẻ bằng $12$\rq\rq\, bằng
	\choice
	{$\dfrac{1}{12}$}
	{$\dfrac{1}{10}$}
	{$\dfrac{2}{15}$}
	{\True $\dfrac{4}{45}$}
	\loigiai{
		Số phần tử của không gian mẫu $n(\Omega)=\mathrm{A}_{10}^2=90$.\\
		Gọi $A$ là biến cố \lq\lq Tổng các số trên $2$ tấm thẻ bằng $12$\rq\rq.\\
		Các cặp thẻ lấy ra có tổng bằng $12$ là $(2; 10)$, $(10; 2)$, $(3; 9)$, $(9; 3)$, $(4; 8)$, $(8; 4)$, $(5; 7)$, $(7; 5)$.
		Suy ra $n(A)=8$.\\
		Xác suất của biến cố $A$ là $\mathrm{P}(A)=\dfrac{n(A)}{n(\Omega)}=\dfrac{8}{90}=\dfrac{4}{45}$.
	}
\end{ex}

