2D1V5-5:
\begin{ex}%[2D1V5-5]
	\immini
	{
			Cho hàm số $y=f(x)=\dfrac{ax+b}{x+c}$ có giá trị lớn nhất trên đoạn $[3;4]$ bằng $7$ và có đồ thị $y=f'(x)$ như hình vẽ (đồ thị hàm số $f'(x)$ có tiệm cận đứng $x=2$ và nhận trục hoành làm tiệm cận ngang).
		\choiceTF
		{\True Đồ thị $y=f'(x)$ có đường tiệm cận đứng là $x=2$}
		{\True Hàm số $f(x)$ nghịch biến trên khoảng $(2;+\infty)$}
		{$3b+2c=-2$}
		{Giá trị nhỏ nhất của hàm số $f(x)$ trên đoạn $[3;4]$ bằng $6$}
	}
	{
		\begin{tikzpicture}[>=stealth,x=1cm,y=1cm,scale=0.5,declare function={xmin=-3;xmax=6;ymin=-5;ymax=2;can=2;}]
			\draw[->] (xmin,0) -- (xmax,0) node[below] {\scriptsize $x$};
			\draw[->] (0,ymin) -- (0,ymax) node[left] {\scriptsize $y$};
			\draw 
			(0,0) node[below left]{\scriptsize $O$}
			(2,0) node[above right]{\scriptsize $2$}
			(0,-1) node[left]{\scriptsize $-1$}
			;
			\draw[dashed,blue] (can,ymin) -- (can,ymax); 
			\clip (xmin,ymin) rectangle (xmax+0.1,ymax+0.1);
			\draw[thick,color=red,samples=150,smooth,domain=xmin:1.3] plot(\x,{-4/pow(\x-2,2)}); 
			\draw[thick,color=red,samples=150,smooth,domain=2.7:xmax] plot(\x,{-4/pow(\x-2,2)}); 
		\end{tikzpicture}
	}

	\loigiai{
		\begin{itemchoice}
			\itemch Từ đồ thị hàm số $y=f'(x)$, đường tiệm cận đứng là $x=2$.
			\itemch Trên khoảng $(2;+\infty)$, đồ thị $y=f'(x)$ nằm dưới trục hoành, nên $f'(x) < 0$, $\forall x \in (2;+\infty)$ nên hàm số $y=f(x)$ nghịch biến trên khoảng $(2;+\infty)$.
			\itemch Ta có $y=f'(x)=\dfrac{ac-b}{(x+c)^2}$.\\
			Từ đồ thị $f'(x)$ có tiệm cận đứng $x=2 \Rightarrow -c=2 \Leftrightarrow c=-2$.\\
			Mặt khác hàm số nghịch biến trên khoảng $(2;+\infty)$ nên trên đoạn $[3;4]$ hàm số cũng nghịch biến.\\
			Suy ra $\max\limits_{[3;4]} f(x) = f(3) = 7 \Leftrightarrow \dfrac{3a+b}{3+c} = 7 \Leftrightarrow 3a+b=7(3-2)=7$.\\
			Lại có từ đồ thị $f'(0)=-1 \Leftrightarrow \dfrac{ac-b}{c^2}=-1 \Leftrightarrow \dfrac{-2a-b}{4}=-1 \Leftrightarrow 2a+b=4$.\\
			Giải hệ ta được $a=3, b=-2$.\\
			Nên $3b+2c=3(-2)+2(-2)=-10 \neq -2$.
			\itemch Vì trên đoạn $[3;4]$ hàm số nghịch biến nên $\min\limits_{[3;4]} f(x) = f(4) = \dfrac{3\cdot 4 - 2}{4 - 2} = 5$.
		\end{itemchoice}
	}
\end{ex}

1D7C2-8:
\begin{ex}%[1D7C2-8]
	\immini[thm]{Một cái bể nước hình nón để ngược như hình vẽ, có chiều cao $51$ cm, bán kính đáy bằng $50$ cm. Một vòi nước chảy vào bể sao cho sau mỗi giây chiều cao mực nước tăng đều lên $2$ cm cho đến khi đầy bể. Hãy tính tốc độ tăng thể tích (m$^3$/s) của nước trong khoảng thời gian một giây ngay trước khi bể đầy. ({\it Kết quả làm tròn đến hàng phần trăm}).
	}{
		\begin{tikzpicture}[scale=1,>=stealth, font=\footnotesize, line join=round, line cap=round]
			\def\h{-3}
			\def\a{2}
			\def\b{.5}
			\begin{scope}%thiết diện vuông góc với trục
				\path
				(0,-4) coordinate (O)
				%($(O)+(\a,0)$) coordinate (B)
				($(O)+(0,\h)$) coordinate (S)
				($(O)!0.4!(S)$) coordinate (O')
				($(O)+(0:\a cm and \b cm)$) coordinate (A)
				($(S)+(0:\a cm and \b cm)$) coordinate (B)
				($(O)+(-10:\a cm and \b cm)$) coordinate (M)
				($(O)+(190:\a cm and \b cm)$) coordinate (N)
				($(O')+(10:0.6*\a cm and 0.6*\b cm)$) coordinate (M')
				($(O')+(170:0.6*\a cm and 0.6*\b cm)$) coordinate (N')
				;
				\fill[cyan!50] (S)--(M')--(N')--cycle;
				\fill[cyan!30] (M') arc (10:170:0.6*\a cm and 0.6*\b cm)--(M') arc (10:-190:0.6*\a cm and 0.6*\b cm);
				\draw (O) ellipse (\a cm and \b cm );
				\draw [dashed] (M') arc (10:170:0.6*\a cm and 0.6*\b cm);
				\draw (M') arc (10:-190:0.6*\a cm and 0.6*\b cm);
				\draw (N)--(S)--(M);
				\draw [dashed] (S)--(O);
				\draw[<->] (O)--(A) node[pos=0.5,above]{$50$ cm}; 
				\draw[<->] (A)--(B) node[pos=0.5,right]{$51$ cm}; 
			\end{scope}
		\end{tikzpicture}
	}
	%\par\shortans[0]{0,02}
	\loigiai{
		Gọi $H=51$ (cm) là chiều cao của bể hình nón và $R=50$ (cm) là bán kính đáy của bể. \\
		Gọi $h$ (cm) là chiều cao mực nước và $r$ (cm) là bán kính mặt nước tại chiều cao $h$. \\
		Ta có $\dfrac{r}{h}=\dfrac{R}{H}\Rightarrow r=\dfrac{R}{H}h=\dfrac{50}{51}h$. \\
		Thể tích nước trong bể khi mực nước có chiều cao $h$ là $V=\dfrac{1}{3}\pi r^2h=\dfrac{1}{3}\pi\left(\dfrac{50}{51}h\right)^2h=\dfrac{2\,500\pi}{7\,803}h^3$. \\
		Vì mỗi giây mực nước tăng đều $2$ cm, nên chiều cao mực nước thời gian một giây ngay trước khi bể đầy là
		\[h_0 = 51 - 2 = 49 \;\text{(cm)}.\]
		Tốc độ tăng thể tích trong khoảng thời gian $1$ giây này chính là lượng thể tích nước tăng thêm từ lúc $h_0=49$ (cm) đến khi $h=51$ (cm).\\
		Vậy lượng thể tích tăng của nước trong khoảng thời gian một giây ngay trước khi bể đầy là
		\[\Delta V=V(51)-V(49)= \dfrac{2\,500\pi}{7\,803}(51^3-49^3)= \dfrac{2\,500\pi \cdot 15\,002}{7\,803} \, \left(\text{cm}^3\right).\]
		Ta có $\dfrac{2\,500\pi\cdot 15\,002}{7\,803}$ cm$^3$ $=\dfrac{2\,500\pi\cdot 15\,002}{7\,803\cdot 10^6}\approx 0{,}02$ m$^3$.\\
		Vậy tốc độ tăng thể tích của nước trong khoảng thời gian một giây ngay trước khi bể đầy khoảng $0{,}02$ (m$^3$/s).
	}
\end{ex}

2H2V2-2:
\begin{ex}%[2H2V2-2]
	Trong không gian $Oxyz$, cho tam giác $ABC$ với $A(1;1;2)$, $B(5;1;-2)$ và $C(3;5;0)$. Các khẳng định sau đúng hay sai?
	\choiceTF
	{$\overrightarrow{AB} \cdot \overrightarrow{BC}=0$}
	{\True Tọa độ vectơ $\overrightarrow{BC}$ là $(-2;4;2)$}
	{Điểm $G\left(\dfrac{7}{3};\dfrac{9}{3};0\right)$ là trọng tâm tam giác $ABC$}
	{\True Điểm $H(a;b;c)$ là chân đường cao hạ từ $A$ xuống $BC$. Khi đó $a+b-c=8$}
	\loigiai{
		Ta có $\overrightarrow{AB}=(4;0;-4), \overrightarrow{BC}=(-2;4;2)$.
		\begin{itemchoice}
			\itemch Do đó $\overrightarrow{AB} \cdot \overrightarrow{BC} = 4 \cdot (-2) + 0 \cdot 4 + (-4) \cdot 2 = -16 \neq 0$.
			\itemch $\overrightarrow{BC}=(-2;4;2)$.
			\itemch $G$ là trọng tâm tam giác $ABC$ nên tọa độ $G$ là $\left(\dfrac{1+5+3}{3};\dfrac{1+1+5}{3};\dfrac{2-2+0}{3}\right) = \left(3;\dfrac{7}{3};0\right)$.
			\itemch Phương trình đường thẳng $BC$ có một vectơ chỉ phương $\overrightarrow{a}(1;-2;-1)$ và đi qua điểm $B(5;1;-2)$ là $\heva{&x=5+t \\ &y=1-2t \\ &z=-2-t}$.\\
			Điểm $H$ thuộc $BC$ nên $H(5+t;1-2t;-2-t)$.\\
			Vậy $\overrightarrow{AH}(4+t;-2t;-4-t)$.\\
			Do $AH$ vuông góc $BC$ nên $\overrightarrow{AH} \cdot \overrightarrow{BC}=0$.
			\begin{align*}
				&-2(4+t) - 4 \cdot 2t + 2(-2-t) = 0 \\
				&\Rightarrow t=-1 \\
				&\Rightarrow H(4;3;-1)
			\end{align*}
			Vậy $a=4; b=3; c=-1$ nên $a+b-c=8$.
		\end{itemchoice}
	}
\end{ex}

2D1V5-6:
\begin{ex}%[2D1V5-6]
	\immini[thm]{Có một hòn đảo nằm trong một vịnh biển, giả sử rằng đường bao sát biển của hòn đảo được mô hình hóa vào hệ trục tọa độ $Oxy$ là một phần bên phải trục tung của đồ thị hàm số bậc ba $y=f(x)=-x^3+3x^2+2$ và giả sử một con đường trong đất liền chạy trên một đường thẳng có phương trình là $y=-9x+60$ như hình vẽ, với đơn vị trên mỗi trục tọa độ là $100$ m. Tập đoàn đầu tư du lịch ST muốn làm một cây cầu vuợt biển có dạng một đoạn thẳng nối từ con đường trong đất liền ra hòn đảo để khai thác du lịch sinh thái. Tính độ dài ngắn nhất (đơn vị mét) của cây cầu cần làm? ({\it Làm tròn kết quả đến chữ số hàng đơn vị}).
	}{
