	\par\shortans[oly]{17}
	\loigiai{
		Gọi $CD=x$ (km) $\Rightarrow DB=8 - x$ (km), điều kiện $0 \le x \le 8$. Khi đó ta có
		\begin{itemize}
			\item $AD=\sqrt{3^2+x^2}=\sqrt{x^2+9} 
			\Rightarrow t_{AD}=\dfrac{\sqrt{x^2+9}}{6}$.
			\item $DB=8 - x \Rightarrow t_{DB}=\dfrac{8 - x}{8}$.
		\end{itemize}
		Khi đó $t=t_{AD}+t_{DB}=\dfrac{\sqrt{x^2+9}}{6}+\dfrac{8 - x}{8}=f(x)$. \\
		Xét $f'(x)=\dfrac{x}{6\sqrt{x^2+9}} - \dfrac{1}{8}$, cho $f'(x)=0 
		\Leftrightarrow x=\dfrac{9\sqrt{7}}{7}$. \\
		Bảng biến thiên của hàm số $f(x)$ với $0 \leq x \le 8$.
