1D3H1-3:
\begin{ex}%[1D3H1-3]
  Giá trị của giới hạn $\lim \left( \sqrt[3]{n^3 - 2n^2} - n \right)$ bằng
  \choice
  {$\dfrac{1}{3}$}
  {\True $-\dfrac{2}{3}$}
  {$1$}
  {$0$}
  \loigiai{
    Ta có
    \allowdisplaybreaks
    \begin{eqnarray*}
      \lim \left( \sqrt[3]{n^3 - 2n^2} - n \right) 
      &=& \lim \dfrac{n^3 - 2n^2 - n^3}{\sqrt[3]{(n^3 - 2n^2)^2}+n \sqrt[3]{n^3 - 2n^2}+n^2} \\
      &=& \lim \dfrac{-2n^2}{\sqrt[3]{(n^3 - 2n^2)^2}+n \sqrt[3]{n^3 - 2n^2}+n^2} \\
      &=& \lim \dfrac{-2}{\sqrt[3]{\left( 1 - \dfrac{2}{n} \right)^2}+n \sqrt[3]{1 - \dfrac{2}{n}}+1}=-\dfrac{2}{3}.
    \end{eqnarray*}
  }
\end{ex}

