1D3H1-5:
\begin{ex}%[1D3H1-5]
	Tìm số hạng tổng quát của cấp số nhân lùi vô hạn khi có tổng bằng $3$ và công bội bằng $\dfrac{2}{3}$.
	\choice
	{\True $\left( \dfrac{2}{3} \right)^{n - 1}$}
	{$\left( \dfrac{2}{3} \right)^n$}
	{$\left( \dfrac{2}{3} \right)^{n + 1}$}
	{$\left( \dfrac{2}{3} \right)^{n + 1}$}
	\loigiai{
		Ta có $S = \dfrac{u_1}{1 - q} \Leftrightarrow 3 = \dfrac{u_1}{1 - \dfrac{2}{3}} \Leftrightarrow u_1 = 1$.
		Cấp số nhân có $
		\begin{cases}
			u_1 = 1 \\
			q = \dfrac{2}{3}
		\end{cases} \Rightarrow u_n = u_1 q^{n-1} = 1 \cdot \left( \dfrac{2}{3} \right)^{n - 1} = \left( \dfrac{2}{3} \right)^{n - 1}$.
	}
\end{ex}

2D1V5-3:
\begin{ex}%[2D1V5-3]
	\immini{
		Cho hàm số $y=f(x)$ có đạo hàm trên $\mathbb{R}$ và $f'(x)$ là hàm số bậc ba có đồ thị là đường cong trong hình vẽ.
		\choiceTF
		{Đồ thị hàm số $g(x)=f(x) - \dfrac{1}{2} x^2+x+2025$ cắt đường thẳng $y=m$ tại bốn điểm phân biệt khi và chỉ khi $g(-1) < m < \min\{g(-3);g(1)\}$}
		{\True Đồ thị hàm số $h(x)=\dfrac{2x+1}{f'(x)}$ có $3$ đường tiệm cận}
		{Hàm số $y=f(x)$ đồng biến trên khoảng $(0;+\infty)$}
		{Hàm số $y=f(x)$ có hai điểm cực trị}
	}
	{
		\begin{tikzpicture}[font=\footnotesize, line join=round, line cap=round, >=stealth,scale=1, yscale=.8]
			\draw[->] (-3.8,0)--(2.2,0) node[below left] {$x$};
			\draw[->] (0,-4.8)--(0,2) node[below left] {$y$};
			\draw (0,0) node[below left] {$O$};
			\foreach \x/\vt in {-3/90,-2/90,-1/90,1/50}{
				\fill[black] (\x,0)circle(1pt) ($(\x,0)+(\vt:2.5mm)$)node{$\x$};
			}
			\foreach \x/\vt in {-4/-40,-2/0}{
				\fill[black] (0,\x)circle(1pt) ($(0,\x)+(\vt:2.5mm)$)node{$\x$};
			}
			\begin{scope}
			  \clip (-3.8,-5) rectangle (2,2);
			  % f'(x)=(x+2)^2*(x - 1)
			  \draw[blue, thick, samples=200, domain=-3.5:1.5, smooth, variable=\x]
			  plot (\x, {(\x+2)^2*(\x - 1)});
			\end{scope}

			% Dashed: điểm (-3, -4)
			\draw[dashed] (-3,0)--(-3,-4)--(0,-4) (-1,0)--(-1,-2)--(0,-2);
		\end{tikzpicture}
	}
	\loigiai{
		\begin{itemchoice}
		\itemch Xét hàm $g(x)=f(x) - \dfrac{1}{2}x^2+x+2025$.
		\immini{
			Ta có $g'(x)=f'(x) - x+1=f'(x) - (x-1)$. \\
			Xét đồ thị hàm số $f'(x)$ và đồ thị hàm số $y=x - 1$, ta thấy
			$$f'(x) - (x-1)=0 \Leftrightarrow \hoac{&x=-3 \\ &x=-1 \\ &x=1.}$$
			Từ đó, ta có bảng biến thiên như sau:
		}
		{
			\begin{tikzpicture}[font=\footnotesize, line join=round, line cap=round, >=stealth,scale=1, yscale=.8]
				\draw[->] (-3.8,0)--(2.2,0) node[below left] {$x$};
				\draw[->] (0,-4.8)--(0,2) node[below left] {$y$};
				\draw (0,0) node[below left] {$O$};
				\foreach \x/\vt in {-3/90,-2/90,-1/90,1/130}{
					\fill[black] (\x,0)circle(1pt) ($(\x,0)+(\vt:2.5mm)$)node{$\x$};
				}
				\foreach \x/\vt in {-4/-40,-2/0}{
					\fill[black] (0,\x)circle(1pt) ($(0,\x)+(\vt:2.5mm)$)node{$\x$};
				}
				\begin{scope}
					\clip (-3.8,-5) rectangle (2,2);
					% f'(x)=(x+2)^2*(x - 1)
					\draw[blue, thick, samples=200, domain=-3.5:1.5, smooth, variable=\x]
					plot (\x, {(\x+2)^2*(\x - 1)});
					\draw[red, thick, domain=-3.5:2.5, variable=\x]
					plot (\x, {\x - 1});
				\end{scope}

				% Dashed: điểm (-3, -4)
				\draw[dashed] (-3,0)--(-3,-4)--(0,-4) (-1,0)--(-1,-2)--(0,-2);
			\end{tikzpicture}
		}
		\begin{center}
		  \begin{tikzpicture}
		    \tkzTabInit[lgt=2, espcl=2]
		    {$x$ / 0.8, $g'(x)$ / 0.8, $g(x)$ / 2}
		    {$-\infty$, $-3$, $-1$, $1$, $+\infty$}
		    \tkzTabLine{, -, 0, +, 0, -, 0, +}
		    \tkzTabVar{+/$+\infty$, -/$g(-3)$, +/$g(-1)$, -/$g(1)$, +/$+\infty$}
		  \end{tikzpicture}
		\end{center}
		Dựa vào bảng biến thiên, ta thấy để phương trình $g(x)=m$ có $4$ nghiệm phân biệt thì $$g(-1) > m > \max\{g(-3);\ g(1)\}.$$
		\itemch Xét hàm số $h(x)=\dfrac{2x+1}{f'(x)}$. Ta có $f'(x)=0 \Leftrightarrow \hoac{&x=1\\&x=-2}$, mà $\heva{ &2(1)+1=3 \neq 0 \\ &2(-2)+1=-3 \neq 0}$, do đó đồ thị hàm số $h(x)=\dfrac{2x+1}{f'(x)}$ có $2$ đường tiệm cận đứng tại $x=1$ và $x=-2$. \\
		  Mặt khác, do bậc mẫu lớn hơn bậc tử nên $\lim\limits_{x \to -\infty} h(x)=\lim\limits_{x \to +\infty} h(x)=0$, do đó đồ thị hàm số $h(x)$ có $1$ đường tiệm cận ngang $y=0$. \\
		  Vậy đồ thị hàm số $h(x)=\dfrac{2x+1}{f'(x)}$ có $3$ đường tiệm cận.
		  \itemch Trên khoảng $(0;+\infty)$, ta thấy $\heva{&f'(x) < 0, x \in (0;1) \\& f'(x) > 0, x \in (1;+\infty)} \Rightarrow$ hàm số $f(x)$ nghịch biến trên khoảng $(0;1)$ và đồng biến trên khoảng $(1;+\infty)$.
		  \itemch Dựa vào đồ thị của hàm số $f'(x)$, ta thấy $f'(x)=0$ có $1$ nghiệm bội lẻ ($x=1$), do đó hàm số $f(x)$ có $1$ điểm cực trị.
		\end{itemchoice}
	}
\end{ex}

0H5V4-4:
\begin{ex}%[0H5V4-4]
	Cho hai vectơ $\overrightarrow{a}, \overrightarrow{b}$ sao cho $|\overrightarrow{a}|=\sqrt{2}, |\overrightarrow{b}|=2$ và hai vectơ $\overrightarrow{x}=\overrightarrow{a}+\overrightarrow{b},\ \overrightarrow{y}=2\overrightarrow{a} - \overrightarrow{b}$ vuông góc với nhau. Tính góc giữa hai véc tơ $\overrightarrow{a}$ và $\overrightarrow{b}$ \textit{(đơn vị độ)}.
	\par\shortans[oly]{90}
	\loigiai{
		Ta có 
		\begin{eqnarray*}
			&&\overrightarrow{x} \perp \overrightarrow{y} 
			\Leftrightarrow \overrightarrow{x} \cdot \overrightarrow{y}=0 \\
			&\Leftrightarrow& \left(\overrightarrow{a}+\overrightarrow{b}\right)\left(2\overrightarrow{a} - \overrightarrow{b}\right)=0 \\
			&\Leftrightarrow& 2a^2 - b^2+\overrightarrow{a}\overrightarrow{b}=0 \\
			&\Leftrightarrow& \overrightarrow{a} \cdot \overrightarrow{b}=2 \cdot \left(\sqrt{2}\right)^2 - 2^2=0 \\
			&\Leftrightarrow& \overrightarrow{a} \perp \overrightarrow{b}
		\end{eqnarray*}
		Vậy góc giữa véc tơ $\overrightarrow{a}$ và $\overrightarrow{b}$ bằng $90$ độ.
	}
\end{ex}

2D1V2-3:
\begin{ex}%[2D1V2-3]
	Tính tổng tất cả các giá trị nguyên của tham số $m$ để hàm số $y=\dfrac{x^2+(m - 1)x+3 - 2m}{x+m}$ đạt cực tiểu tại $x=-1$.
	\par\shortans[oly]{2}
	\loigiai{
		Ta có $y=\dfrac{x^2+(m - 1)x+3 - 2m}{x+m}=x - 1+\dfrac{3 - m}{x+m} \Rightarrow y'=1 - \dfrac{3 - m}{(x+m)^2} 
		\Rightarrow y''=\dfrac{2(3 - m)}{(x+m)^3}$. \\
		Hàm số đạt cực tiểu tại $x=-1$ khi
		$$\heva{&y'(-1)=0 \\ &y''(-1) > 0}
		\Leftrightarrow \heva{&1-\dfrac{3 - m}{(-1+m)^2}=0 \\ &\dfrac{2(3 - m)}{(-1+m)^3} > 0}
		\Leftrightarrow \heva{&\hoac{&\heva{&m=-1 \\ &m=2} \\ &1 < m < 3}}
		\Leftrightarrow m=2.$$
		Vậy $m=2$ thoả mãn điều kiện.
	}
\end{ex}

1H4V3-5:
\begin{ex}%[1H4V3-5]
	Cho hình tứ diện $ABCD$ có tất cả các cạnh bằng $6$. Gọi $M, N$ lần lượt là trung điểm của $CA, CB$. $P$ là điểm trên cạnh $BD$ sao cho $BP=2PD$. Gọi $(H)$ là hình giới hạn bởi giao tuyến của mặt phẳng $(MNP)$ với các mặt của tứ diện $ABCD$. Tính diện tích hình $(H)$ (kết quả làm tròn đến hàng phần trăm).
	\par\shortans[oly]{8,93}
	\loigiai{
		\begin{center}
			\begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth, declare function={a=5; b=4; h=3; goc=200;}]
				% 1. Định nghĩa các đỉnh
				\path (0,0) coordinate (A) 
				(0:a) coordinate (B)++(goc:b) coordinate (C)
				% Tính trung điểm M, N
				($(A)!0.5!(C)$) coordinate (M)
				($(C)!0.5!(B)$) coordinate (N)
				(intersection of B--M and A--N) coordinate (O)++(90:h) coordinate (D)
				% Tính điểm chia tỉ lệ (Tâm tỉ cự D=2, B=1 nghĩa là P gần D hơn)
				($(B)!2/3!(D)$) coordinate (P)
				($(A)!2/3!(D)$) coordinate (Q);
				\draw[dashed] (A)--(B);
				\draw (A)--(C)--(B)--(D)--(A) (C)--(D);
				\draw[thick, blue] (M)--(Q) (N)--(P);
				\draw[thick, blue, dashed] (M)--(N) (Q)--(P);
				\foreach \diem/\vt in {A/180, B/0, C/-90, D/90, M/-135, N/-45, P/45, Q/135}{
					\fill (\diem) circle (1pt) ($(\diem)+(\vt:3mm)$) node {$\diem$};
				}
			\end{tikzpicture} \qquad
			\begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth]
				% 1. Định nghĩa các điểm
				\path (0,0) coordinate (M)
				(3,0) coordinate (N)
				(0.5,3.5) coordinate (Q)
				(2.5,3.5) coordinate (P)
				(0.5,0) coordinate (I)
				(2.5,0) coordinate (J);

				% 2. Vẽ đa giác và các đường cao
				\draw (M)--(N)--(P)--(Q)--cycle;
				\draw (Q)--(I) (P)--(J);

				% 3. Vẽ kí hiệu góc vuông bằng toạ độ tương đối (++)
				% Góc QIN: Tại I, dịch sang phải 0.2, lên 0.2, sang trái 0.2
				\draw (I) ++(0.2,0) -- ++(0,0.2) -- ++(-0.2,0);
				% Góc PJM: Tại J, dịch sang trái 0.2, lên 0.2, sang phải 0.2
				\draw (J) ++(-0.2,0) -- ++(0,0.2) -- ++(0.2,0);

				% 4. Vẽ điểm và gắn nhãn bằng vòng lặp
				\foreach \diem/\vt in {M/-135, N/-45, Q/135, P/45, I/-90, J/-90}{
					\fill (\diem) circle (1pt) ($(\diem)+(\vt:3mm)$) node {$\diem$};
				}
			\end{tikzpicture} 
		\end{center}
		Dễ thấy $MN \parallel AB \Rightarrow (MNP) \parallel AB$. \\
		Gọi $Q$ là giao điểm của $(MNP)$ với $AD \Rightarrow (MNPQ) \parallel AB \Leftrightarrow PQ \parallel AB \Rightarrow \dfrac{DQ}{DA}=\dfrac{DP}{DB}=\dfrac{1}{3}$. \\
		Vậy hình $(H)$ giới hạn bởi giao tuyến của mặt phẳng $(MNP)$ với các mặt của tứ diện $ABCD$ là hình thang $MNPQ$ với hai đáy $MN, PQ$. \\
		Xét tam giác $ACD$ có $
		  \heva{& \dfrac{AM}{AC}=\dfrac{1}{2} \Rightarrow AM=3 \\ &\dfrac{AQ}{AD}=\dfrac{2}{3} \Rightarrow AQ=4}$. \\
		Tam giác $AMQ$ có $MQ^2=AM^2+AQ^2 - 2 \cdot AM \cdot AQ \cdot \cos A$ \\
		  $\Rightarrow MQ=\sqrt{3^2+4^2 - 2 \cdot 3 \cdot 4 \cdot \cos 60^\circ}=\sqrt{13}$. \\
		Tương tự, $PN=\sqrt{PB^2+BN^2 - 2 \cdot PB \cdot BN \cdot \cos B}=\sqrt{13}$. \\
		Xét tam giác $ADB$ có $QP \parallel AB \Rightarrow \dfrac{QP}{AB}=\dfrac{QD}{AD}=\dfrac{DP}{DB}=\dfrac{1}{3} \Rightarrow QP=2$. \\
		Xét tam giác $ABC$ có $MN \parallel AB \Rightarrow \dfrac{MN}{AB}=\dfrac{CM}{CA}=\dfrac{CN}{CB}=\dfrac{1}{2} \Rightarrow MN=3$.\\
		Hình thang $MNPQ$ có hai cạnh bên $QM=PN$ và hai đáy $MN \neq QP$ nên suy ra $MNPQ$ là hình thang cân. \\
		Kẻ đường cao $QI, PJ$ ($I, J \in MN$), khi đó ta có
		\begin{itemize}
		    \item $QP=IJ \Rightarrow MI=JN=\dfrac{MN - PQ}{2}=\dfrac{1}{2}$
		    \item $QI=PJ=\sqrt{QM^2 - MI^2}=\sqrt{(\sqrt{13})^2 - \left(\frac{1}{2}\right)^2}=\dfrac{\sqrt{51}}{2}$
		\end{itemize}
		Suy ra $S_{MNPQ}=QI \cdot \dfrac{QP+MN}{2}=\dfrac{5\sqrt{51}}{4} \approx 8{,}93$.
	}
\end{ex}

1D6H3-3:
\begin{ex}%[1D6H3-3]
	Tập hợp nghiệm của bất phương trình $\log_{0{,}5} x > -1$ là
	\choice
	{\True $(0;2)$}
	{$(-\infty;2)$}
	{$(0;+\infty)$}
	{$(2;+\infty)$}
	\loigiai{
		ĐKXĐ: $x > 0$. 

		BPT $\Leftrightarrow x < 0{,}5^{-1} \Leftrightarrow x < 2 $.
		Vậy $S = (0;2).$

		\textit{Lưu ý:} Khi giải bất phương trình lôgarit dạng $\log_a x > b$, học sinh cần đặc biệt chú ý hai vấn đề sau:
		\begin{itemize}
			\item \textbf{Điều kiện xác định:} Luôn phải đặt điều kiện cho biểu thức dưới dấu lôgarit dương ($x > 0$). Đây là bước dễ bị bỏ sót dẫn đến việc chọn nhầm đáp án $(-\infty; 2)$.
			\item \textbf{Cơ số $a$:} 
			\begin{itemize}
				\item Nếu $a > 1$: Bất phương trình giữ nguyên chiều.
				\item Nếu $0 < a < 1$: Bất phương trình phải \textbf{đổi chiều}. Trong bài toán này, cơ số\\ $a = 0{,}5 < 1$ nên từ $\log_{0{,}5} x > -1$ ta phải đổi chiều thành $x < 0{,}5^{-1}$.
			\end{itemize}
			\item Kết hợp điều kiện $x > 0$ và $x < 2$, ta được tập nghiệm chính xác là $(0; 2)$.
		\end{itemize}
	}
\end{ex}

2H5C3-8:
\begin{ex}%[2H5C3-8]
	Trong không gian $Oxyz$, cho mặt phẳng $(P) \colon y - 1 = 0$, đường thẳng $d \colon \heva{&x = 1 \\ &y = 2 - t \\ &z = 1}$ và hai điểm $A(-1; -3; 11)$, $B\left(\dfrac{1}{2}; 0; 8\right)$. Hai điểm $M, N$ thuộc mặt phẳng $(P)$ sao cho $M$ luôn cách đường thẳng $d$ một khoảng bằng $2$ và $NA = 2NB$. Khoảng cách nhỏ nhất giữa hai điểm $M$ và $N$ bằng bao nhiêu?
	\shortans[oly]{$1$}
	\loigiai{

		Mặt phẳng $(P)$ có VTPT $\vec{n}_P = (0; 1; 0)$, đường thẳng $d$ có VTCP $\vec{u}_d = (0; -1; 0)$. 

		Nhận thấy $\vec{u}_d$ cùng phương với $\vec{n}_P$ nên $d \perp (P)$. 

		Giao điểm của $d$ và $(P)$ là $I_1(1; 1; 1)$. 
		Vì $d \perp (P)$ tại $I_1$ nên khoảng cách từ $M \in (P)$ đến $d$ chính là đoạn $MI_1 = 2$. 

		Do đó tập hợp các điểm $M$ là đường tròn $(C_1)$ tâm $I_1(1; 1; 1)$, bán kính $R_1 = 2$ nằm trong $(P)$.


		Điểm $N \in (P)$ nên $N(x; 1; z)$. Từ $NA = 2NB \Leftrightarrow NA^2 = 4NB^2$
		$$\Leftrightarrow(x+1)^2 + (1+3)^2 + (z-11)^2 = 4\left[\left(x-\dfrac{1}{2}\right)^2 + (1-0)^2 + (z-8)^2\right]$$
		$$\Leftrightarrow 3x^2 - 6x + 3z^2 - 42z + 123 = 0 \Leftrightarrow (x-1)^2 + (z-7)^2 = 9.$$
		Do đó $N$ thuộc đường tròn $(C_2)$ tâm $I_2(1; 1; 7)$, bán kính $R_2 = 3$.


		\begin{center}
			\begin{tikzpicture}[scale=0.7, font=\footnotesize, line join=round, line cap=round, >=stealth]
				% Vẽ hệ trục tọa độ trong mặt phẳng y=1 (chỉ vẽ Ox, Oz để minh họa)
				\draw[->] (-2.5,0) -- (5,0) node[below] {$x$};
				\draw[->] (0,-1.5) -- (0,11) node[left] {$z$};
				\node[below right] at (0,0) {$O$};

				% Vẽ đường tròn C1
				\coordinate (I1) at (1,1);
				\draw[thick, blue] (I1) circle (2);
				\fill (I1) circle (2pt) node[above right] {$I_1(1;1)$};

				% Vẽ đường tròn C2
				\coordinate (I2) at (1,7);
				\draw[thick, blue] (I2) circle (3);
				\fill (I2) circle (2pt) node[right] {$I_2(1;7)$};

				% Vẽ đoạn nối tâm và khoảng cách MN min
				\draw[dashed] (I1) -- (I2);
				\draw[ultra thick, red] (1,3) -- (1,4);
				\node[right] at (1,3.5) {$MN_{\min}$};

				% Ký hiệu bán kính
				\draw[<->] (I1) -- (3,1) node[midway, below] {$R_1=2$};
				\draw[<->] (I2) -- (-2,7) node[midway, above] {$R_2=3$};
			\end{tikzpicture}
		\end{center}
		Cả $M$ và $N$ cùng nằm trong mặt phẳng $y=1$. 

		Khoảng cách giữa hai tâm: 			
		$I_1I_2 = \sqrt{(1-1)^2 + (1-1)^2 + (7-1)^2} = 6$.

		Khoảng cách nhỏ nhất giữa hai điểm $M$ và $N$ là:

		$$MN_{\min} = I_1I_2 - R_1 - R_2 = 6 - 2 - 3 = 1.$$

	}
\end{ex}

